        return random.choice(unvisited_directions)
    else:
        # Backtrack to a room with unvisited directions
        for step in reversed(path):
            for direction, room in rooms[step].items():
                if room not in visited_rooms:
                    return direction
        return None

def explore_rooms():
    current_room = "Солярий"
    visited_rooms.add(current_room)
    path.append(current_room)

    while True:
