        if direction is None:
            print("ӘЗЕР")
            break

        next_room = rooms[current_room][direction]
        print(f"БАР: {direction}")

        if next_room not in visited_rooms:
            visited_rooms.add(next_room)
            path.append(next_room)

        current_room = next_room

